import pytest

from bedrock_protocol import v924, v944, v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.UpdateClientInputLocks{Locks: packet.ClientInputLockCamera |
#   packet.ClientInputLockMovement | packet.ClientInputLockJump}
CAMERA_MOVEMENT_JUMP = bytes.fromhex("46")

# generated by gophertunnel b8bd735:
# &packet.UpdateClientInputLocks{Locks: 8190}
ALL_CATEGORIES = bytes.fromhex("fe3f")

# generated by gophertunnel b8bd735:
# &packet.UpdateClientInputLocks{Locks: 0xffffffff}
MAX = bytes.fromhex("ffffffff0f")

# generated by gophertunnel 0381a95:
# &packet.UpdateClientInputLocks{Locks: 6, Position: mgl32.Vec3{1, 2, 3}}
V924 = bytes.fromhex("060000803f0000004000004040")

# generated by gophertunnel 428fb16:
# &packet.UpdateClientInputLocks{Locks: 6}
V944 = bytes.fromhex("06")

GOLDENS = [
    pytest.param(
        v2225.UpdateClientInputLocksPacket(input_lock_component_data=70),
        CAMERA_MOVEMENT_JUMP,
        id="camera-movement-jump",
    ),
    pytest.param(
        v2225.UpdateClientInputLocksPacket(input_lock_component_data=8190), ALL_CATEGORIES, id="all-categories"
    ),
    pytest.param(v2225.UpdateClientInputLocksPacket(input_lock_component_data=0xFFFFFFFF), MAX, id="max"),
    pytest.param(
        v924.UpdateClientInputLocksPacket(input_lock_component_data=6, server_pos=v924.Vec3(x=1.0, y=2.0, z=3.0)),
        V924,
        id="v924-with-server-pos",
    ),
    pytest.param(v944.UpdateClientInputLocksPacket(input_lock_component_data=6), V944, id="v944-without-server-pos"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_update_client_input_locks_is_packet_196(version):
    assert version.PACKETS[196] is version.UpdateClientInputLocksPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_client_input_locks_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_client_input_locks_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
